<script lang="ts">
 import {tick} from 'svelte';import {page} from '$app/state';
 import DigitalComponents from '$lib/components/digital/DigitalComponents.svelte';import {base} from '$app/paths';
 import GameCard from '$lib/components/GameCard.svelte';import Accessories from '$lib/components/Accessories.svelte';
 import {allCards,kindNames,type Card} from '$lib/data/game';
 let kind=$state('all'), query=$state(''), backs=$state(false), selected=$state<Card|null>(null), dialog:HTMLDialogElement;
 $effect(()=>{kind=page.url.searchParams.get('collection')==='digital'?'digital':'all';});
 let visible=$derived(allCards.filter(c=>(kind==='all'||c.kind===kind)&&`${c.name} ${c.title} ${c.brief} ${c.detailed}`.toLowerCase().includes(query.toLowerCase())));
 async function inspect(card:Card){selected=card;await tick();dialog.showModal();}
</script>
<svelte:head><title>Component gallery — Higher Powers</title><meta name="description" content="Explore the layered digital soul tiles, Divine Favor, Sanctuary and Purgatory, all 27 cards, and printable table accessories."/></svelte:head>
<main id="main" class="gallery-main">{#if kind!=='digital'}<section class="page-intro"><p class="eyebrow">THE HEAVENLY COLLECTION</p><h1>Every soul has its place.</h1><p>A painterly collection for the screen and the table.<br/>Explore the digital components, or inspect all 27 cards.</p><div class="actions"><a class="text-link" href={`${base}/gallery/print`}>Make a printable set</a><a class="text-link" href={`${base}/gallery/launchers`}>Launcher artwork</a><a class="text-link" href={`${base}/downloads/higher-powers-layered-art.zip`} download>Download layered artwork · 26 MB</a></div></section>
{/if}
 <section aria-label="Component collection">{#if kind!=='digital'}<div class="gallery-controls"><nav class="tabs" aria-label="Component categories">{#each [['digital','Digital table'],['all','All cards · 27'],['angel','Angels · 12'],['decree','Decrees · 10'],['judgment','Judgments · 5'],['accessories','Table essentials']] as [value,label]}<button aria-pressed={kind===value} onclick={()=>kind=value}>{label}</button>{/each}</nav>{#if kind!=='digital'&&kind!=='accessories'}<div class="search-row"><label>Search<input type="search" bind:value={query} placeholder="Name, power, or rule"/></label><label class="checkbox"><input type="checkbox" bind:checked={backs}/>Show card backs</label></div>{/if}</div>{/if}
 {#if kind==='digital'}<DigitalComponents/>{:else if kind==='accessories'}<div class="accessory-gallery"><Accessories type="favor"/><Accessories type="zones"/><Accessories type="score"/></div><p class="accessory-note">Bring a standard 106-tile Rummikub set, racks, an opaque bag, five coins, and pencils. Use separate rack space for Scales commitments. No replacement tiles or racks need printing.</p><a class="button" href={`${base}/downloads/higher-powers-accessories-a4.pdf`} download>Download table essentials</a>
 {:else}<p class="result-count" aria-live="polite">{visible.length} cards</p><div class="gallery-grid">{#each visible as card (card.id)}<div class="gallery-item"><div class="card-wrap"><GameCard {card} back={backs}/><button onclick={()=>inspect(card)} aria-label={`Inspect ${card.name}`}></button></div><p><span>{kindNames[card.kind]}</span><strong>{card.name}</strong></p></div>{:else}<div class="empty-state"><h2>No cards found.</h2><p>Try another name, power, or rule.</p><button onclick={()=>{query='';kind='all';}}>Reset filters</button></div>{/each}</div>{/if}
 </section>
</main>
<dialog bind:this={dialog} onclose={()=>selected=null}><button class="close-dialog" onclick={()=>dialog.close()}>Close ×</button>{#if selected}<div class="inspection"><div class="inspection-card"><GameCard card={selected} back={backs}/></div><div class="inspection-copy"><p class="eyebrow">{kindNames[selected.kind]}</p><h2>{selected.name}</h2><div class="prose"><p>{selected.brief}</p></div><a href={`${base}/rules.html#reference`}>Read the full rules in the rulebook</a>{#if backs}<a href={`${base}/art/cards/back-${selected.kind}.webp`} download>Download card back artwork</a>{:else}<a href={`${base}/art/layers/${selected.id}.svg`} download>Download layered SVG source</a>{/if}</div></div>{/if}</dialog>

